import{_ as r}from"./chunks/824e3b9231d2c7af8ce9.CvtpRolK.js";import{_ as a,C as l,o as i,c as o,j as p,a as n,E as s,a6 as h}from"./chunks/framework.CnPv4DE1.js";const k=JSON.parse('{"title":"微型教育商业模式（如何将你的知识变现）","description":"","frontmatter":{"title":"微型教育商业模式（如何将你的知识变现）","originalTitle":"The Micro Education Business Model (How To Monetize Your Knowledge)","date":"2023-04-14","originalUrl":"https://thedankoe.com/letters/the-new-wave-of-micro-businesses-monetize-your-knowledge/","minutes":11,"sourceHash":"bfcc40dd1f89824606810c249f4d2344fb034e4af9a46ee00c3d17466f3aaf2f","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-new-wave-of-micro-businesses-monetize-your-knowledge/"}]]},"headers":[],"relativePath":"letters/the-new-wave-of-micro-businesses-monetize-your-knowledge.md","filePath":"letters/the-new-wave-of-micro-businesses-monetize-your-knowledge.md"}'),u={name:"letters/the-new-wave-of-micro-businesses-monetize-your-knowledge.md"};function c(d,e,m,f,w,b){const t=l("ArticleMeta");return i(),o("div",null,[e[0]||(e[0]=p("h1",{id:"微型教育商业模式-如何将你的知识变现",tabindex:"-1"},[n("微型教育商业模式（如何将你的知识变现） "),p("a",{class:"header-anchor",href:"#微型教育商业模式-如何将你的知识变现","aria-label":'Permalink to "微型教育商业模式（如何将你的知识变现）"'},"​")],-1)),s(t),e[1]||(e[1]=h('<p><a href="https://www.youtube.com/embed/XgAMayF-JZY?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>当我刚开始创业时，我觉得做自由职业是唯一的选择。</p><p>我觉得自己不够权威，无法建立个人品牌。</p><p>我没有钱为电商品牌订购高质量的产品。</p><p>我甚至不知道咨询是什么。</p><p>代理机构和自由职业工作往往被推销给初学者，这是有充分理由的：</p><ul><li>你可以免费学习技能（或者通过课程学习，比起大学学位要便宜得多）。</li><li>你不需要花时间去积累受众就能找到客户（尽管我强烈建议你要积累受众）。</li><li>你每个月只需要3-4个客户就能获得丰厚的收入。</li></ul><p>这是个闭着眼睛都能做出的选择。</p><p>我现在依然认为这是个很棒的选项。</p><p>36%的劳动力是自由职业者。</p><p>随着去中心化和<a href="https://thedankoe.com/the-future-of-the-creator-economy-my-bold-prediction/" target="_blank" rel="noreferrer">未来工作方式的转变</a>，我相信这个数字在未来十年将飙升至90%以上。（我喜欢做这种看似妄想的预测）。</p><p>每个人都将成为自由职业者。</p><p>也就是说，直到他们进化为创作者，将自己的知识产品化，并作为一人企业进行规模化扩张为止。前提是他们想逃离那种“饥一顿饱一顿”的客户周期。</p><p>尽管如此，选择依然是无穷无尽的。</p><p>无尽的细分领域等你进入。</p><p>无尽的技能等你学习。</p><p>无尽的获客策略等你测试。</p><p>难怪在线业务会让人感到如此不知所措。</p><p>这一切都太新了。</p><p>它存在的时间并不长……也许就几十年？甚至连几十年都不到？这真的挺疯狂的。</p><p>而且你找不到任何大学课程在教授创作者们正在使用的这些策略。</p><p>所以，对于那些认为自由职业是你唯一选择的人，我想向你们展示一些新东西。</p><p>但首先，我需要打破你的一些限制性信念。</p><h2 id="教育企业是最有意义的商业模式-特别是对初学者而言" tabindex="-1">教育企业是最有意义的商业模式（特别是对初学者而言） <a class="header-anchor" href="#教育企业是最有意义的商业模式-特别是对初学者而言" aria-label="Permalink to &quot;教育企业是最有意义的商业模式（特别是对初学者而言）&quot;">​</a></h2><p>人们喜欢唱衰教育类企业。</p><p>他们认为这只是一群人在诈骗和操纵，因为信息不是有形的。</p><p>实际上，这是目前最有意义且最以结果为导向的商业模式。</p><p>尤其是在当前的学校体系已然崩溃的情况下。</p><p>如果没有在线教育行业，没有那些卖50美元课程的“骗子”（我买得实在太多了），我就不会拥有一个能谈论我热爱之事的七位数业务。就这么简单。</p><p>你<em>只有</em>在在线课程中才能找到最新的、具体的、相关的信息。</p><p>如果你能找到那句让你豁然开朗的话，谁在乎你是不是在这里或那里浪费了50美元呢。</p><p>大多数人只是太缺乏耐心了。</p><p>他们可以接受花4年时间上大学，拿着不到六位数的薪水，甚至被剥夺了自己的人生，却不愿相信一个去中心化的个体基于经验和结果所教授的内容。这可能需要花费差不多同样的时间，但一旦你开窍了，你将看到指数级的结果。</p><p>调整你的期望。</p><p>要想理解信息和教育的重要性（尤其是在商业中），我们必须理解进化。</p><p>动物试图复制其基因中的信息。</p><p>虽然人类也会这么做，但我们还有一个独特的特征，那就是我们寻求复制我们意识中的信息。</p><p>我们不仅试图让我们的肉体形态存活下来，也试图让我们的精神形态存活下来。</p><p>我们的“精神形态”就是我们的自我意识。</p><p>我们投射并传达我们所认同的想法、信念和价值观。</p><p>毫不夸张地说，我们试图在每一次互动中复制“我们是谁”。</p><p>而当别人不认同我们紧紧抱持的信念时，争论就随之而来了。</p><p>父母将他们“自我”的碎片灌输给孩子。</p><p>而这些父母也是根据他们从自己父母那里继承的宗教意识形态、职业路径和信仰，做着同样的事。</p><p>在每一次互动中，你都在将你的意识内容在精神上播种到他人的头脑中。</p><p>好了，在我听起来像个疯子之前，我想说，这为什么重要？</p><p>教育是进步与进化的支柱。</p><p>教育改变人类行为。</p><p>教育创造了对社会有贡献、能赚更多钱并创造就业机会的有用之才。</p><p>教育行业只会继续增长，而那些不接受它的人可能会被时代的浪潮抛下。</p><p>顺便说一句，我在我的<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学大师班（Digital Economics masterclass）</a>中教授了所有这些内容。</p><h2 id="教育与创作者经济" tabindex="-1">教育与创作者经济 <a class="header-anchor" href="#教育与创作者经济" aria-label="Permalink to &quot;教育与创作者经济&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>一个“创作者”依靠三大支柱：</p><ul><li>灵感</li><li>教育</li><li>娱乐</li></ul><p>有些人孤注一掷于其中一个。</p><p>就像Mr. Beast纯粹是一个娱乐创作者一样。</p><p>一些像“百万富翁激励（Millionaire Motivation）”这样的主题账号则是基于灵感的。</p><p>许多教程账号则只基于教育。</p><p>在我眼里，全盘兼顾的方法才是最好的。</p><p>就像Joe Rogan将上述所有元素融合在一起（因为他以<em>他真实的自我</em>作为杠杆）。</p><p>或者像我这样，利用个人经验来激发灵感，利用哲学思考来提供娱乐，利用硬核建议来进行教育。</p><p>将这三者结合使用，能创造出一个可持续的商业模式，在这个模式中<a href="https://thedankoe.com/the-most-profitable-niche-is-you-how-to-create-your-niche/" target="_blank" rel="noreferrer">你就是细分领域</a>。</p><p>未来属于那些占据最多心智资产的人。</p><p>换句话说，未来属于那些能够捕捉注意力并复制其自我价值层面的人。</p><p>你需要专注于让你的想法深深印在读者的脑海中。</p><p>就像当我陷入情绪低谷时，我会想起埃克哈特·托利（Eckhart Tolle）所著的《当下的力量》（The Power Of Now）中的核心思想。</p><p>我将我的进步归功于他，并传递他的作品。</p><p>谁知道他因为我微妙但持续的贡献赚了多少钱。</p><p>不要再把内容当作一种赚钱的手段了。</p><p>你的想法会在排名前十的播客节目中被提及吗？</p><p>你的想法会出现在畅销书的前言中吗？</p><p>你的想法会在爆款视频和圈子紧密的时事通讯中被提及吗？</p><p>为了影响力而写作，收入自然会随之而来（参见：<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2小时作者（2 Hour Writer）</a>）。</p><p>为了做到这一点，你必须发展自我。</p><p>个人发展是关于解决你自己的问题。</p><p>商业是关于解决别人的问题。</p><p>所以，发展自我，通过教育业务记录下解决方案，然后去发展他人。</p><p>把<em>你的生活</em>当成你毕生的事业，你会改变人类的发展轨迹，让它变得更好。</p><p>在不知不觉中，你以一种能够引发积极行为改变的方式影响着个体。</p><p>从个体到集体，你让世界变得更加美好。即使你并不想这么去想。</p><h2 id="三点微型商业模式" tabindex="-1">三点微型商业模式 <a class="header-anchor" href="#三点微型商业模式" aria-label="Permalink to &quot;三点微型商业模式&quot;">​</a></h2><p>我不想让你感到不知所措。</p><p>我想给你一个实用的商业模式，你今天就可以开始建立它。</p><p>刚开始会极其困难（万事开头难）。</p><p>但精通之路往往如此……刚开始很难，但随着时间的推移，它会变得越来越令人愉悦。</p><p>如果你能通过练习、迭代和坚持跨越那道困难的门槛，一切都会迎刃而解。</p><p>注意我是怎么说<em>迭代</em>的。</p><p>如果一件事行不通，就尝试点别的。</p><p>“尝试”这个词意味着你正在接受一个你有能力应对的挑战。</p><p>这为进入心流状态（或称最高享受状态）创造了软条件。</p><p>迷茫时，就去学习。</p><p>有了方向，就去行动。</p><p>去犯错。去出洋相。去把事情搞砸，这样你才有改进的空间。当你又感到迷茫时，重复这个过程。</p><p>如果我想进一步减少我的工作量，我依然会保持这个结构，只不过分发到更少的社交平台上。</p><p>大多数在Twitter上取得成功的创作者都在效仿这种结构，创造了属于他们自己的小小的数字现实，让他们的追随者可以栖息其中。</p><h3 id="_1-创办一份时事通讯-newsletter" tabindex="-1">1) 创办一份时事通讯（Newsletter） <a class="header-anchor" href="#_1-创办一份时事通讯-newsletter" aria-label="Permalink to &quot;1) 创办一份时事通讯（Newsletter）&quot;">​</a></h3><p>没人想创办时事通讯，因为他们没有任何订阅者。</p><p>这正是你应该开始做的一个原因。</p><p>没人正在看着。</p><p>你是宁愿在没有订阅者的时候练习写作？还是想等到那种“要把第一期写给5000人看”的恐惧让你完全无法动笔时再开始？</p><p>为什么你要关注撰写时事通讯？</p><ul><li>它能建立最大的权威（短内容的吸引力是有限的）。</li><li>你拥有你所获取的受众（社交平台随时可能宕机）。</li><li>这是你向在乎你的人销售产品或服务的地方（而不是在社交媒体上发垃圾信息，看起来像个骗子）。</li></ul><p>长篇内容应该是你业务的支柱。</p><p>它迫使你在思想背后挖掘深度。</p><p>这样一来，你就能吸引到真正愿意为你买单的铁杆受众（而且你不会在其他平台上沦为一个肤浅的建议提供者）。</p><p>当你拥有了长内容，你就可以跳过别人让你去学的绝大多数销售和营销小把戏了。</p><p>你该如何开始撰写时事通讯？</p><p><strong>搜寻高表现的想法</strong></p><p>不是动画。</p><p>不是剪辑上的字幕。</p><p>不是推文的结构。</p><p>不是可操作的清单。</p><p>不是完美的个人简介。</p><p>不是色彩丰富的缩略图。</p><p>是人们从他们喜欢的人那里收集的想法。</p><p>像动画这样的东西当然有帮助。</p><p>它们能吸引注意力，并让你的品牌质量瞬间超越99%的创作者。</p><p>所以，如果你有很棒的想法并希望将其可视化，去看看我的动画机构 <a href="https://www.keyframe.design/" target="_blank" rel="noreferrer">Keyframe</a>（仅限成熟创作者）。</p><p>为了找到高表现的想法：</p><ul><li>按“最受欢迎”筛选你最喜欢的YouTuber的视频，并研究它们的标题。</li><li>注册Medium.com，选择你的兴趣，每天研究首页推荐的标题。</li><li>阅读书籍，直到某个新颖的想法引起你的注意，把它写下来，并运用到你的写作、视频和演讲中。</li></ul><p>要产生最多的想法，我绝对最喜欢的方式是研究热门推文。</p><p>人们依然低估了Twitter的价值。</p><p>然而，它迫使人们将他们要说的话浓缩成最具影响力的280个字符（大多数人只会把他们的观点拖得很长，从而破坏了互动潜力）。</p><p>这就是为什么我在Instagram上的纯文字帖子表现优于大多数其他基于图片的创作者。</p><p>我使用 <a href="https://thedankoe.com/get/tweethunter" target="_blank" rel="noreferrer">TweetHunter</a> 来筛选我喜欢的账号，吸收他们最棒的想法，并定时发布我最好的内容。</p><p><strong>研究框架并把它们当作你的辅助轮</strong></p><p>既然你有了想法，你就需要练习如何以一种有说服力、有价值且有影响力的方式将其表达出来。</p><p>换句话说，你需要以一种能阐明痛点、问题和解决方案的方式去写作，让人们产生共鸣并<em>想要</em>去付诸实践。我在<a href="https://thedankoe.com/value-creation-the-skill-that-built-my-one-person-business/" target="_blank" rel="noreferrer">价值创造信件（Value Creation letter）</a>中写过这一点。</p><ul><li>研究表现出色的推文，解构它们的样子和运作原理，并用你独特的想法来练习写作。</li><li>研究像PAS和AIDA这样的小型文案框架，来利用人类心理学。</li><li>对于长篇内容，去研究PASTOR，或者我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2小时作者（2 Hour Writer）</a>中提供的系统。</li><li>从一个创作者而不是消费者的视角去消费社交媒体和营销内容，并且再说一遍……去练习。</li></ul><p>想法只有被消费了，才能产生影响力。</p><p>如果你不能捕获并留住注意力，就没人会去消化你在说的话。</p><p><strong>分发到所有平台</strong></p><p>一旦你写了一篇时事通讯，你就可以：</p><ul><li>把它用作 YouTube 脚本（大多数人都是即兴发挥，结果视频平平无奇）。</li><li>把它上传到博客上，这样你就可以终生转发它（如果其中包含你的产品或服务，你就是这样卖出它们的）。</li></ul><p>这是我上传长篇内容的仅有的两个地方，但如果你愿意，你可以去 Medium 等更多平台。</p><h3 id="_2-浓缩成中篇形式" tabindex="-1">2) 浓缩成中篇形式 <a class="header-anchor" href="#_2-浓缩成中篇形式" aria-label="Permalink to &quot;2) 浓缩成中篇形式&quot;">​</a></h3><p>如果你想在 Twitter、Instagram 或 LinkedIn 等短内容平台上脱颖而出，你应该通过中篇内容来证明你的权威。</p><p>我是这样做的：</p><ul><li>提取我时事通讯中的主要观点。</li><li>勾勒出一个更短、更简洁的帖子大纲。</li><li>把它写成一条 Twitter 推文串（thread）（因为你会被迫把你的想法浓缩成最有价值的内容）。</li><li>将推文串的长度限制在最多 10-15 条推文。</li><li>这样一来，只需花几分钟的时间，它们就可以变成 Instagram 和 LinkedIn 的轮播图（carousel）。</li></ul><p>就这么简单。</p><p>相比于短内容，中篇形式能建立更多的权威，并产生更多的销售额、潜在客户和订阅量。</p><p>你吸引注意力的时间越长，你作为品牌获得的感知价值就越高。</p><h3 id="_3-拆解成短篇形式" tabindex="-1">3) 拆解成短篇形式 <a class="header-anchor" href="#_3-拆解成短篇形式" aria-label="Permalink to &quot;3) 拆解成短篇形式&quot;">​</a></h3><p>短篇形式是你的增长和测试机制。</p><p>你推文串中的每一部分都可以变成一条独立的推文。</p><p>你也可以通读你的时事通讯，并以这种方式产生灵感。</p><p>或者，当你在寻找灵感时，你可以在 TweetHunter 里定时发布推文。</p><p>为什么用 Twitter？</p><p>因为它是一个试验场。</p><p>几乎我所有的时事通讯灵感都来自以前表现良好的推文。</p><p>这样我就知道，时事通讯、YouTube 视频和推文串也会表现得很好。</p><p>你就这样创建了一个自给自足的内容生态系统，你可以从中源源不断地榨取一辈子的价值。</p><h2 id="先建立分发渠道-再进行变现" tabindex="-1">先建立分发渠道，再进行变现 <a class="header-anchor" href="#先建立分发渠道-再进行变现" aria-label="Permalink to &quot;先建立分发渠道，再进行变现&quot;">​</a></h2><p>以上所有内容将形成几个你必须在每天和每周去撬动的杠杆。</p><p>这就是你建立受众、流量来源或分发渠道的方法。</p><p>然后，你需要将这些流量引向某个地方以便变现。</p><p>我以前已经讲过无数次变现的方法了：</p><ul><li>研究你的兴趣</li><li>创办一家服务型企业</li><li>扩大受众群体</li><li>免费工作</li><li>开发你的流程</li><li>提高价格</li><li>重复第 5-6 步</li><li>将你的流程产品化</li><li>扩大你的受众，你的收入也会随之增加</li></ul><p>但是，有了这个由三部分组成的微型企业方法，还有其他几种途径。</p><p>以 Shaan Puri 为例，他把自己的时事通讯做到了 10 万订阅者，并从赞助中每月赚取 5 万美元。</p><p>如果你把时事通讯拍成 YouTube 视频，你可以接受赞助并通过 AdSense 获得广告收入。</p><p>Maxx Chewning 最近提到，他每年通过 AdSense 赚取约 10 万美元，但通过赞助每年能赚 100 万美元。</p><p>再加上像 Justin Welsh 的内容系统那样的数字产品，砰！你就增加了第三条每月 10 万美元的收入来源。</p><p>毫不夸张地说，你唯一要做的就是专注（以正确的方式）建立受众群体，一旦做到了，你这辈子就不愁了。</p><p>你有无数种变现选择，而且 <em>不需要</em> 通过乞求捐款来变现。</p><p>提供价值，建立分发渠道，要求获得报酬。</p><p>就是这样。</p><p>享受你的一周。</p><p>—— 丹·柯伊 (Dan Koe)</p><hr><p><a href="/en/letters/the-new-wave-of-micro-businesses-monetize-your-knowledge">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',172))])}const T=a(u,[["render",c]]);export{k as __pageData,T as default};
